const input = $input.first().json;
const query = input.query || {};

const code = query.code;
const state = query.state;

if (!code || !state) {
  return [{
    json: {
      valid: false,
      error: 'params_missing'
    }
  }];
}

return [{
  json: {
    valid: true,
    code,
    state
  }
}];

const flowDataStr = $input.first().json.flowData;
const code = $('Validate Params').first().json.code;
const state = $('Validate Params').first().json.state;

let flowData;
try {
  flowData = JSON.parse(flowDataStr);
} catch (e) {
  return [{
    json: {
      success: false,
      error: 'parse_error'
    }
  }];
}

return [{
  json: {
    success: true,
    code: code,
    state: state,
    user_id: flowData.user_id,
    code_verifier: flowData.code_verifier,
    client_id: flowData.client_id || 'chess-bot',
    redirect_uri: flowData.redirect_uri || 'https://lichess.azy.solutions/webhook/lichess-oauth-callback',
    provider: flowData.provider || 'lichess'
  }
}];

const tokenResponse = $input.first().json;
const flowData = $('Parse Flow Data').first().json;

// Calculer expiration
const expiresIn = tokenResponse.expires_in || 5184000; // 60 jours par défaut
const expiresAt = new Date(Date.now() + expiresIn * 1000).toISOString();

// TTL en secondes (expires_in - 1 heure de marge, minimum 1 jour)
const ttl = Math.max(expiresIn - 3600, 86400);

return [{
  json: {
    user_id: flowData.user_id,
    state: flowData.state,
    token_data: JSON.stringify({
      access_token: tokenResponse.access_token,
      token_type: tokenResponse.token_type || 'Bearer',
      expires_in: expiresIn,
      expires_at: expiresAt,
      provider: 'lichess',
      scopes: ['challenge:read', 'challenge:write', 'board:play'],
      created_at: new Date().toISOString()
    }),
    ttl: ttl
  }
}];

